import{_ as o,C as r,o as n,c as i,a3 as t,E as d}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"System Architecture","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"System Architecture | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/architecture"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/architecture"}]]},"headers":[],"relativePath":"catter/design/architecture.md","filePath":"en/catter/design/architecture.md","lastUpdated":1793090554000}'),c={name:"catter/design/architecture.md"};function s(h,e,l,m,u,p){const a=r("Mermaid");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h1><p>Catter is a build-process interception and analysis tool organized around <strong>runtimes</strong>. A runtime is the mechanism that actually captures process creation: every command invocation made by the build system becomes an event catter can handle, and is executed according to the decision of the session&#39;s handlers -- run as-is, modified, dropped, or aborted.</p><p>Handler authors only need to understand two things:</p><ol><li><strong>What a runtime is, and which one the current session uses</strong> -- covered here and in <a href="./runtime">Runtime</a>.</li><li><strong>The lifecycle of a session</strong> -- its start and end at the build level, and each command before and after it runs.</li></ol><h2 id="the-runtime-abstraction" tabindex="-1">The runtime abstraction <a class="header-anchor" href="#the-runtime-abstraction" aria-label="Permalink to &quot;The runtime abstraction&quot;">​</a></h2><p>&quot;Intercepting process creation&quot; differs greatly in feasibility across platforms: hooks are the most general, but are restricted on some platforms (for example, macOS requires special development entitlements). Catter therefore abstracts capture mechanisms as runtimes. One runtime is one capture implementation; the handlers see the commands it captures, whichever it is.</p><p>catter captures a build with <code>inject</code>; given <code>--from</code>, it replays a recorded build instead of running one. A handler learns which from the session&#39;s <code>initialize</code> message, whose <code>mode</code> is <code>inject</code>, or <code>replay</code> for a recorded build.</p><p>Today <code>inject</code> (based on hooks) is the only capture mechanism; <code>env</code> and <code>eslogger</code> are planned. The principles, platform limitations, and capability differences of each mechanism are covered in <a href="./runtime">Runtime</a>.</p><h2 id="handlers" tabindex="-1">Handlers <a class="header-anchor" href="#handlers" aria-label="Permalink to &quot;Handlers&quot;">​</a></h2><p>A session&#39;s handlers decide on its commands and are told of its events. They are the built-in the command runs, if any (<code>compile-commands</code>, <code>tree</code>, <code>targets</code>), which runs inside catter, and the <a href="./../scripting/handlers">handlers</a> given with <code>--handler</code> or <code>--connect</code>: programs that catter speaks the <a href="./handler-protocol">handler protocol</a> to. The handlers form a chain: the built-in first, then the others in the order of the command line.</p><h2 id="session-lifecycle" tabindex="-1">Session lifecycle <a class="header-anchor" href="#session-lifecycle" aria-label="Permalink to &quot;Session lifecycle&quot;">​</a></h2>',11)),d(a,{id:"mermaid-42",graph:"sequenceDiagram%0A%20%20%20%20participant%20Handler%0A%20%20%20%20participant%20Catter%20as%20catter%20daemon%0A%20%20%20%20participant%20Runtime%20as%20Runtime%20(capture%20mechanism)%0A%20%20%20%20participant%20Build%20as%20Build%20system%0A%0A%20%20%20%20Catter-%3E%3EHandler%3A%20initialize%20(the%20build%2C%20the%20mode)%0A%20%20%20%20Handler--%3E%3ECatter%3A%20What%20it%20wants%20to%20be%20told%0A%20%20%20%20Catter-%3E%3ERuntime%3A%20Start%20the%20build%0A%20%20%20%20loop%20For%20each%20captured%20command%0A%20%20%20%20%20%20%20%20Runtime-%3E%3ECatter%3A%20Command%20event%0A%20%20%20%20%20%20%20%20Catter-%3E%3EHandler%3A%20command%0A%20%20%20%20%20%20%20%20Handler--%3E%3ECatter%3A%20Action%20(skip%20%2F%20drop%20%2F%20abort%20%2F%20modify%20%2F%20edit)%0A%20%20%20%20%20%20%20%20Catter-%3E%3ERuntime%3A%20Execute%20according%20to%20action%0A%20%20%20%20%20%20%20%20Runtime-%3E%3ECatter%3A%20Execution%20result%0A%20%20%20%20%20%20%20%20Catter-%3E%3EHandler%3A%20exit%0A%20%20%20%20end%0A%20%20%20%20Runtime--%3E%3ECatter%3A%20Build%20process%20finished%0A%20%20%20%20Catter-%3E%3EHandler%3A%20finish%0A"}),e[1]||(e[1]=t('<h3 id="build-level-initialize-finish" tabindex="-1">Build level: initialize / finish <a class="header-anchor" href="#build-level-initialize-finish" aria-label="Permalink to &quot;Build level: initialize / finish&quot;">​</a></h3><p><strong><code>initialize</code></strong> starts the session, before the build: it carries the build command, its working directory and the runtime. The handler answers with whether it decides on each command, which events it wants to be told, which commands it wants to hear of, and whether commands carry their environment and what catter makes of them.</p><p><strong><code>finish</code></strong> comes once the build has ended, with the build&#39;s exit code. A handler writes its final output here.</p><h3 id="command-level-command-error-exit" tabindex="-1">Command level: command / error / exit <a class="header-anchor" href="#command-level-command-error-exit" aria-label="Permalink to &quot;Command level: command / error / exit&quot;">​</a></h3><p><strong><code>command</code></strong> comes for each captured command before it runs: its working directory, executable, full argument vector, the parent command that started it, and, if the handler asked, its environment and what catter makes of it: the compiler, archiver or tool it runs, and what its arguments say. A handler that decides answers with an action; one that does not is only told, and the build never waits for it.</p><p><strong><code>error</code></strong> comes instead when catter could not capture a command: the message says why.</p><p><strong><code>exit</code></strong> comes after each command finishes, with its exit code and how long it took. Handlers can aggregate statistics or failures here.</p><h2 id="actions-separating-handler-semantics-from-execution-mechanics" tabindex="-1">Actions: separating handler semantics from execution mechanics <a class="header-anchor" href="#actions-separating-handler-semantics-from-execution-mechanics" aria-label="Permalink to &quot;Actions: separating handler semantics from execution mechanics&quot;">​</a></h2><p>&quot;How to handle a command&quot; is expressed at two layers in catter:</p><ol><li><strong>Handler layer</strong> (what handlers decide): <code>skip</code> / <code>drop</code> / <code>abort</code> / <code>modify</code> / <code>edit</code> -- semantic and independent of the mechanism.</li><li><strong>Protocol layer</strong> (what catter-proxy, or on Windows the hook, carries out): <code>DROP</code> / <code>RUN</code> / <code>FAIL</code> -- the concrete execution mechanics.</li></ol><p>The session maps handler-layer actions to protocol-layer actions, whichever runtime reports the commands:</p><table tabindex="0"><thead><tr><th>Handler action</th><th>Semantics</th><th>Protocol mapping</th></tr></thead><tbody><tr><td><code>skip</code></td><td>Execute as-is, catter does not intervene</td><td><code>RUN</code> (run with hooks mounted; descendants can still be captured)</td></tr><tr><td><code>drop</code></td><td>Do not execute; return exit code 0</td><td><code>DROP</code></td></tr><tr><td><code>abort</code></td><td>Abort the whole build and report an error</td><td><code>FAIL</code> (this command and every later one fail without running)</td></tr><tr><td><code>modify</code></td><td>Execute the command with replacement data</td><td><code>RUN</code> (carrying the modified command)</td></tr><tr><td><code>edit</code></td><td>Execute the command with edited arguments</td><td><code>RUN</code> (carrying the edited command)</td></tr></tbody></table><p>Keep in mind:</p><ul><li><strong><code>skip</code> is not &quot;ignore the whole subtree&quot;</strong>. <code>skip</code> only lets this command run as-is; its descendants are still captured and still reach the handlers.</li><li><strong><code>abort</code> ends the session</strong>, as a handler that fails does: the command, and every command the build starts after it, fail without running, and once the build has ended catter prints the reason and exits 1.</li></ul><h2 id="components-and-processes" tabindex="-1">Components and processes <a class="header-anchor" href="#components-and-processes" aria-label="Permalink to &quot;Components and processes&quot;">​</a></h2><p>A single catter run involves several processes and components. They are all part of the runtime implementation, and handler authors usually do not need to know about them:</p><table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td><code>catter</code> (daemon)</td><td>Runs the session&#39;s handlers, receives commands over IPC and returns decisions</td></tr><tr><td><code>catter-proxy</code></td><td>On Linux and macOS: stands in for each command the hook intercepted, and for the build command, which catter starts through it; relays IPC</td></tr><tr><td>hook shared library</td><td>The capture carrier of the inject runtime; injected into build processes to intercept process creation; on Windows it asks the daemon itself and starts each program</td></tr></tbody></table><p>They are <strong>implementation details of the inject runtime</strong>; the runtime abstraction itself is the center of the architecture. See <a href="./runtime">Runtime</a> and <a href="./hook-mechanism">Hook mechanism</a>.</p>',18))])}const b=o(c,[["render",s]]);export{g as __pageData,b as default};
